/**
 * Download manifest for semantic search (docs/semantic-search.md §8.1).
 *
 * Every file is verified against the SHA-256 and size below before it is
 * used. Model files come from Hugging Face at a pinned commit; the runtime
 * (worker bundle + ONNX Runtime wasm) comes from this plugin's GitHub release
 * and its hashes are generated by the build (assets.generated.ts).
 *
 * Download URLs can go through user-configured mirrors (mirrors.ts); the
 * local `name` never does, so installed files stay valid across mirrors.
 */
import { GENERATED_RUNTIME_FILES } from "./assets.generated";
import { buildGithubUrl, buildHfUrl, MirrorSettings } from "./mirrors";

export interface AssetEntry {
	/** Path relative to the model directory, always with "/" separators. */
	name: string;
	/** Effective download URL (official or through a mirror). */
	url: string;
	size: number;
	sha256: string;
	source: "github" | "huggingface";
}

export const MODEL_ID = "onnx-community/embeddinggemma-2-ONNX";
/** Pinned Hugging Face commit (main @ 2026-10-06). Never use "main" here. */
export const MODEL_REVISION = "daa72c51243991dfcaf9f9137d2c573d8f7790c0";
/** GitHub repository that publishes the runtime release assets. */
export const RELEASE_REPO = "stmoonar/oss-gallery-plugin-obsidian";

/** No mirrors: official Hugging Face and GitHub URLs. */
export const OFFICIAL_SOURCES: MirrorSettings = { hfEndpoint: "", githubMirror: "" };

const HF_HOST = "huggingface.co";

/**
 * Model files mirror their URL below the model directory
 * (`huggingface.co/<model>/resolve/<revision>/<file>`), which is the layout
 * the worker's fs cache reads (§4.3), so the worker never re-downloads them.
 */
function modelAsset(file: string, size: number, sha256: string): AssetEntry {
	const path = `${MODEL_ID}/resolve/${MODEL_REVISION}/${file}`;
	return {
		name: `${HF_HOST}/${path}`,
		url: `https://${HF_HOST}/${path}`,
		size,
		sha256,
		source: "huggingface",
	};
}

/** Strip the local host directory: `<repo>/resolve/<revision>/<file>`. */
function hfPath(asset: AssetEntry): string {
	return asset.name.slice(HF_HOST.length + 1);
}

/** text + vision encoders only (no audio), dtype q4. Sizes in bytes. Official URLs. */
export const MODEL_ASSETS: readonly AssetEntry[] = [
	modelAsset("config.json", 5031, "8d011bfe08b5e345bbe0b81e5c6fd02c381920b345b986047bc2a33ce7b90d1d"),
	modelAsset("processor_config.json", 1788, "168f6a08522f3ce5dea596d94d003af2fd691742d4f41fe1f9d8cce76bfbf69c"),
	modelAsset("preprocessor_config.json", 560, "9344893f8d0573a46ebb2ca54c03f56d044cea194c8dcfb1f4d652240ac21daa"),
	modelAsset("tokenizer_config.json", 1599, "17bd5d6e9364ca49a534e1502076593317c298d4a663623091ed45388f004874"),
	modelAsset("chat_template.jinja", 1016, "4b852efc0b9960283e735363331e6f325b33bc74bdbaa076f595bc4e9b94d85e"),
	modelAsset("tokenizer.json", 32170510, "4d777ef5bdc1aa36227abdfb77c3e49e7b9c892d16e1b6bda41c393504828be4"),
	modelAsset("onnx/model_q4.onnx", 490742, "f9eeba97acddf139b8ee2ddf04bc30dceafa88de93fadf74d7644e0d61a477a9"),
	modelAsset("onnx/model_q4.onnx_data", 174028800, "c3975f2d1ab7a1878ae31a7d7a9b7804a827aff3800b60dfceafce21cac3df49"),
	modelAsset("onnx/vision_encoder_q4.onnx", 159400, "7ea284226d4938f0ad921ab091f1d80a9ca699aa802984ef5cd5eec4f4761d96"),
	modelAsset("onnx/vision_encoder_q4.onnx_data", 108957696, "0a9d6c927334f152a33dd90874f65d6ea5228999abe6a450d3f7813677fa704c"),
];

/** Local directory (relative to the model dir) of a plugin version's runtime. */
export function runtimeDirName(pluginVersion: string): string {
	return `runtime/${pluginVersion}`;
}

/**
 * Runtime files for this plugin version. They are versioned on disk so vaults
 * running different plugin versions can share one model directory.
 */
export function getRuntimeAssets(
	pluginVersion: string,
	mirrors: MirrorSettings = OFFICIAL_SOURCES
): AssetEntry[] {
	return GENERATED_RUNTIME_FILES.map((f) => ({
		name: `${runtimeDirName(pluginVersion)}/${f.file}`,
		url: buildGithubUrl(
			`https://github.com/${RELEASE_REPO}/releases/download/${pluginVersion}/${f.file}`,
			mirrors.githubMirror
		),
		size: f.size,
		sha256: f.sha256,
		source: "github" as const,
	}));
}

/** Model files, downloaded through the configured Hugging Face endpoint. */
export function getModelAssets(mirrors: MirrorSettings = OFFICIAL_SOURCES): AssetEntry[] {
	return MODEL_ASSETS.map((asset) => ({
		...asset,
		url: buildHfUrl(hfPath(asset), mirrors.hfEndpoint),
	}));
}

export function getAllAssets(
	pluginVersion: string,
	mirrors: MirrorSettings = OFFICIAL_SOURCES
): AssetEntry[] {
	return [...getRuntimeAssets(pluginVersion, mirrors), ...getModelAssets(mirrors)];
}

export function totalSize(assets: readonly AssetEntry[]): number {
	return assets.reduce((sum, a) => sum + a.size, 0);
}
